"""Ansible inventory for the Proxmox nodes, derived from site.yml on every run."""

from __future__ import annotations

from pathlib import Path
from typing import Any

from .. import paths
from ..models import DEFAULT_ANSIBLE_VARS, SiteConfig
from ..utils import dump_yaml

HEADER = (
    "# Generated by pvc from site.yml. Do not edit:\n"
    "# the next run overwrites this file. Put node settings in site.yml.\n"
)

GROUP = "pve_hosts"
BECOME_PASSWORD_SECRET = "proxmox_become_password"


def configurable_nodes(site: SiteConfig) -> list[str]:
    return [name for name, node in site.nodes.items() if node.configure]


def build_hosts_inventory(site: SiteConfig, *, become_password: bool = False) -> dict[str, Any]:
    """One host per node with `configure: true`, all in the `pve_hosts` group.

    Exporters bind to the node's own address. VM-oriented `site.ansible_vars` are left out on
    purpose; use `host_config.vars` for node-wide variables.
    """
    config = site.host_config
    proxmox = site.proxmox

    hosts: dict[str, Any] = {}
    for name in configurable_nodes(site):
        address = site.nodes[name].address
        hosts[name] = {
            "ansible_host": address,
            "sys_hostname": name,
            "node_exporter_enabled": config.node_exporter.enabled,
            "node_exporter_listen_address": f"{address}:{config.node_exporter.port}",
            "node_exporter_port": config.node_exporter.port,
            "node_exporter_open_ufw": False,
            "smartctl_exporter_enabled": config.smartctl_exporter.enabled,
            "smartctl_exporter_listen_address": f"{address}:{config.smartctl_exporter.port}",
            "smartctl_exporter_devices": list(config.smartctl_exporter.devices),
        }

    all_vars: dict[str, Any] = {
        **DEFAULT_ANSIBLE_VARS,
        "ansible_user": proxmox.ssh_user,
        "ansible_port": proxmox.ssh_port,
    }
    if proxmox.ssh_key:
        all_vars["ansible_ssh_private_key_file"] = str(Path(proxmox.ssh_key).expanduser())
    if proxmox.ssh_user != "root":
        all_vars["ansible_become"] = True
        if become_password:
            all_vars["ansible_become_password"] = "{{ %s }}" % BECOME_PASSWORD_SECRET
    all_vars.update(config.vars)

    return {
        "all": {
            "vars": all_vars,
            "hosts": hosts,
            "children": {GROUP: {"hosts": {name: {} for name in hosts}}},
        }
    }


def write_hosts_inventory(inventory: dict[str, Any], path: Path | None = None) -> Path:
    path = path or paths.SITE_HOSTS_INVENTORY
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(dump_yaml(inventory, header=HEADER))
    return path
